const {chromium}=require('playwright'),fs=require('fs'),os=require('os'),path=require('path'),http=require('http'),assert=require('assert/strict'),{execFileSync}=require('child_process');
const repo=path.resolve(__dirname,'../..'),dir=fs.mkdtempSync(path.join(os.tmpdir(),'sambaadm-employee-'));let role='admin';
execFileSync('go',['test','./internal/web','-run','^TestWorkspaceBrowserFixtures$','-count=1'],{cwd:repo,env:{...process.env,SAMBAADM_WEB_FIXTURE_DIR:dir}});
const server=http.createServer((req,res)=>{const p=new URL(req.url,'http://localhost').pathname,file=p.startsWith('/static/')?path.join(repo,'internal/web',p):path.join(dir,role+'-'+p.slice(1)+'.html');if(!fs.existsSync(file)){res.writeHead(404).end();return;}res.setHeader('Content-Type',file.endsWith('.js')?'application/javascript':file.endsWith('.css')?'text/css':'text/html');res.end(fs.readFileSync(file));});
(async()=>{await new Promise(r=>server.listen(0,'127.0.0.1',r));const browser=await chromium.launch({headless:true});try{
 const page=await browser.newPage({viewport:{width:1200,height:900}});const errors=[];page.on('pageerror',e=>errors.push(e.message));let applied=0,plan;
 await page.route('**/api/v1/**',async route=>{const req=route.request(),p=new URL(req.url()).pathname.slice(7);let result=[];if(p==='/users')result=['anna','ivan'].map(login=>({samAccountName:login,dn:'CN='+login+',DC=example,DC=com',enabled:true}));if(p==='/directory/tree')result={kind:'domain',label:'example.com',dn:'DC=example,DC=com',children:[]};if(p==='/users/bulk'){const body=req.postDataJSON();assert.deepEqual(body.logins,['anna','ivan']);plan={id:'a'.repeat(32),revision:'revision',action:body.action,state:'ready',items:body.logins.map(login=>({login,state:'ready',message:'Отключить учётную запись'}))};result=plan;}if(p.endsWith('/apply')){assert.equal(req.postDataJSON().confirm,true);assert.ok(req.headers()['x-csrf-token']);applied++;result={...plan,state:'partial',items:[{login:'anna',state:'done',message:'Результат подтверждён'},{login:'ivan',state:'failed',message:'Данные изменились'}]};}await route.fulfill({json:result});});
 await page.goto('http://127.0.0.1:'+server.address().port+'/users');assert.equal(await page.locator('.bulk-actions').isVisible(),false);await page.getByLabel('Выбрать всех показанных пользователей',{exact:true}).check();await page.getByRole('button',{name:'Отключить',exact:true}).click();const dialog=page.getByRole('dialog');await dialog.getByRole('button',{name:'Применить изменения',exact:true}).click();assert.equal(applied,0);await dialog.getByLabel('Подтверждаю перечисленные изменения',{exact:true}).check();await dialog.getByRole('button',{name:'Применить изменения',exact:true}).click();await dialog.getByText('Данные изменились',{exact:true}).waitFor();await dialog.getByRole('button',{name:'Скачать отчёт JSON',exact:true}).waitFor();await page.setViewportSize({width:390,height:844});assert.equal(await dialog.evaluate(e=>e.scrollWidth>e.clientWidth),false);await page.screenshot({path:path.join(dir,'bulk-mobile.png'),fullPage:true});assert.deepEqual(errors,[]);console.log('PASS: selection, preview, confirmation, individual results, download and mobile');
 }finally{await browser.close();server.close();}})().catch(e=>{console.error(e);server.close();process.exitCode=1;});
